/**
 * Suburban Maple Crescent street environment & neighborhood props.
 * Renders directly from the single-source-of-truth `StreetPropsBundle` generated by
 * `GameSimulation`, guaranteeing 100% alignment between visual props and AABB colliders.
 */

import { useEffect, useMemo, useRef } from 'react';
import { useThree } from '@react-three/fiber';
import * as THREE from 'three';
import type { StreetPropsBundle } from '../world/streetProps';
import { STREET_CONFIG } from '../world/streetLayout';
import { getContactShadowTexture, getProceduralTextureLibrary } from './proceduralTextures';

interface StreetEnvironmentProps {
  streetProps: StreetPropsBundle;
  roadLength: number;
  isNight: boolean;
}

/** Composite 10-part parked suburban car grounded with radial contact shadow. */
function ParkedCar({
  position,
  rotationY,
  color,
  isNight,
  shadowTex,
}: {
  position: [number, number, number];
  rotationY: number;
  color: string;
  isNight: boolean;
  shadowTex: THREE.CanvasTexture;
}) {
  return (
    <group position={position} rotation={[0, rotationY, 0]}>
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.02, 0]}>
        <planeGeometry args={[2.5, 4.9]} />
        <meshBasicMaterial map={shadowTex} transparent depthWrite={false} opacity={0.72} />
      </mesh>
      <mesh position={[0, 0.56, 0]} castShadow receiveShadow>
        <boxGeometry args={[1.86, 0.62, 4.35]} />
        <meshStandardMaterial color={color} roughness={0.34} metalness={0.35} />
      </mesh>
      <mesh position={[0, 1.12, -0.18]} castShadow receiveShadow>
        <boxGeometry args={[1.64, 0.54, 2.25]} />
        <meshStandardMaterial color={color} roughness={0.32} metalness={0.35} />
      </mesh>
      <mesh position={[0, 1.12, 0.96]} rotation={[-0.22, 0, 0]}>
        <boxGeometry args={[1.52, 0.44, 0.06]} />
        <meshStandardMaterial color="#27323b" roughness={0.1} metalness={0.5} />
      </mesh>
      <mesh position={[0, 1.12, -1.32]} rotation={[0.22, 0, 0]}>
        <boxGeometry args={[1.5, 0.44, 0.06]} />
        <meshStandardMaterial color="#27323b" roughness={0.1} metalness={0.5} />
      </mesh>
      <mesh position={[0.83, 1.12, -0.18]}>
        <boxGeometry args={[0.04, 0.4, 2.02]} />
        <meshStandardMaterial color="#27323b" roughness={0.1} metalness={0.5} />
      </mesh>
      <mesh position={[-0.83, 1.12, -0.18]}>
        <boxGeometry args={[0.04, 0.4, 2.02]} />
        <meshStandardMaterial color="#27323b" roughness={0.1} metalness={0.5} />
      </mesh>
      <mesh position={[0, 0.34, 2.2]} castShadow>
        <boxGeometry args={[1.9, 0.2, 0.14]} />
        <meshStandardMaterial color="#2f3235" roughness={0.75} />
      </mesh>
      <mesh position={[0, 0.34, -2.2]} castShadow>
        <boxGeometry args={[1.9, 0.2, 0.14]} />
        <meshStandardMaterial color="#2f3235" roughness={0.75} />
      </mesh>
      {[-0.64, 0.64].map((hx) => (
        <mesh key={`hl_${hx}`} position={[hx, 0.62, 2.19]}>
          <boxGeometry args={[0.32, 0.16, 0.05]} />
          <meshStandardMaterial
            color="#f4efd8"
            emissive="#ffe29c"
            emissiveIntensity={isNight ? 1.8 : 0.1}
            roughness={0.15}
          />
        </mesh>
      ))}
      {[-0.66, 0.66].map((hx) => (
        <mesh key={`tl_${hx}`} position={[hx, 0.62, -2.19]}>
          <boxGeometry args={[0.3, 0.14, 0.05]} />
          <meshStandardMaterial
            color="#8e2c24"
            emissive="#c43225"
            emissiveIntensity={isNight ? 1.4 : 0.1}
            roughness={0.2}
          />
        </mesh>
      ))}
      {[-0.92, 0.92].map((wx) =>
        [-1.36, 1.36].map((wz) => (
          <group key={`w_${wx}_${wz}`} position={[wx, 0.33, wz]} rotation={[0, 0, Math.PI / 2]}>
            <mesh castShadow>
              <cylinderGeometry args={[0.33, 0.33, 0.24, 14]} />
              <meshStandardMaterial color="#202224" roughness={0.92} />
            </mesh>
            <mesh>
              <cylinderGeometry args={[0.19, 0.19, 0.26, 12]} />
              <meshStandardMaterial color="#8c9298" metalness={0.75} roughness={0.3} />
            </mesh>
          </group>
        )),
      )}
    </group>
  );
}

/** Composite Street Lamp with metal pole, arm, luminaire hood, and warm emissive globe. */
function StreetLamp({
  position,
  rotationY,
  isNight,
}: {
  position: [number, number, number];
  rotationY: number;
  isNight: boolean;
}) {
  return (
    <group position={position} rotation={[0, rotationY, 0]}>
      <mesh position={[0, 0.22, 0]} castShadow>
        <cylinderGeometry args={[0.14, 0.18, 0.44, 10]} />
        <meshStandardMaterial color="#34383c" metalness={0.65} roughness={0.45} />
      </mesh>
      <mesh position={[0, 3.1, 0]} castShadow>
        <cylinderGeometry args={[0.065, 0.09, 5.7, 10]} />
        <meshStandardMaterial color="#3b4045" metalness={0.65} roughness={0.42} />
      </mesh>
      <mesh position={[0, 5.85, 0.72]} rotation={[Math.PI / 2, 0, 0]} castShadow>
        <cylinderGeometry args={[0.045, 0.05, 1.5, 8]} />
        <meshStandardMaterial color="#3b4045" metalness={0.65} roughness={0.42} />
      </mesh>
      <mesh position={[0, 5.82, 1.45]}>
        <boxGeometry args={[0.36, 0.12, 0.46]} />
        <meshStandardMaterial color="#2b2f33" metalness={0.6} roughness={0.4} />
      </mesh>
      <mesh position={[0, 5.72, 1.45]}>
        <sphereGeometry args={[0.14, 10, 10]} />
        <meshStandardMaterial
          color={isNight ? '#ffebbd' : '#d2d6d8'}
          emissive="#ffca72"
          emissiveIntensity={isNight ? 3.2 : 0}
          roughness={0.2}
        />
      </mesh>
    </group>
  );
}

export function StreetEnvironment({ streetProps, roadLength, isNight }: StreetEnvironmentProps) {
  const { gl } = useThree();
  const textures = useMemo(
    () => getProceduralTextureLibrary(Math.min(4, gl.capabilities.getMaxAnisotropy())),
    [gl],
  );
  const shadowTex = useMemo(() => getContactShadowTexture(), []);

  const trunkRef = useRef<THREE.InstancedMesh>(null);
  const crownARef = useRef<THREE.InstancedMesh>(null);
  const crownBRef = useRef<THREE.InstancedMesh>(null);
  const bushRef = useRef<THREE.InstancedMesh>(null);
  const fencePostRef = useRef<THREE.InstancedMesh>(null);
  const fenceRailRef = useRef<THREE.InstancedMesh>(null);

  // Populate InstancedMeshes directly from streetProps (exact 1:1 match with physics colliders)
  useEffect(() => {
    const dummy = new THREE.Object3D();
    const color = new THREE.Color();

    if (trunkRef.current && crownARef.current && crownBRef.current) {
      streetProps.trees.forEach((t, i) => {
        dummy.position.set(t.x, 1.65 * t.s, t.z);
        dummy.rotation.set(0, t.rot, 0);
        dummy.scale.set(t.s, t.s, t.s);
        dummy.updateMatrix();
        trunkRef.current!.setMatrixAt(i, dummy.matrix);

        dummy.position.set(t.x, 3.85 * t.s, t.z);
        dummy.scale.set(t.s * 1.15, t.s * 0.95, t.s * 1.15);
        dummy.updateMatrix();
        crownARef.current!.setMatrixAt(i, dummy.matrix);
        color.set(t.tint);
        crownARef.current!.setColorAt(i, color);

        dummy.position.set(t.x + 0.55 * t.s, 4.7 * t.s, t.z - 0.35 * t.s);
        dummy.scale.set(t.s * 0.82, t.s * 0.78, t.s * 0.82);
        dummy.updateMatrix();
        crownBRef.current!.setMatrixAt(i, dummy.matrix);
        color.set(t.tint).offsetHSL(0, 0, 0.04);
        crownBRef.current!.setColorAt(i, color);
      });
      trunkRef.current.instanceMatrix.needsUpdate = true;
      crownARef.current.instanceMatrix.needsUpdate = true;
      crownBRef.current.instanceMatrix.needsUpdate = true;
      if (crownARef.current.instanceColor) crownARef.current.instanceColor.needsUpdate = true;
      if (crownBRef.current.instanceColor) crownBRef.current.instanceColor.needsUpdate = true;
      trunkRef.current.computeBoundingSphere();
      crownARef.current.computeBoundingSphere();
      crownBRef.current.computeBoundingSphere();
    }

    if (bushRef.current) {
      streetProps.bushes.forEach((b, i) => {
        dummy.position.set(b.x, 0.42 * b.s, b.z);
        dummy.rotation.set(0, i * 1.1, 0);
        dummy.scale.set(b.s * 1.2, b.s * 0.85, b.s * 1.0);
        dummy.updateMatrix();
        bushRef.current!.setMatrixAt(i, dummy.matrix);
        color.set(b.tint);
        bushRef.current!.setColorAt(i, color);
      });
      bushRef.current.instanceMatrix.needsUpdate = true;
      if (bushRef.current.instanceColor) bushRef.current.instanceColor.needsUpdate = true;
      bushRef.current.computeBoundingSphere();
    }

    if (fencePostRef.current) {
      streetProps.fencePosts.forEach((p, i) => {
        dummy.position.set(p.x, 0.78, p.z);
        dummy.rotation.set(0, 0, 0);
        dummy.scale.set(1, 1, 1);
        dummy.updateMatrix();
        fencePostRef.current!.setMatrixAt(i, dummy.matrix);
      });
      fencePostRef.current.instanceMatrix.needsUpdate = true;
      fencePostRef.current.computeBoundingSphere();
    }

    if (fenceRailRef.current) {
      streetProps.fenceRails.forEach((r, i) => {
        dummy.position.set(r.x, 0.72, r.z);
        dummy.rotation.set(0, r.rotY, 0);
        dummy.scale.set(r.len, 1, 1);
        dummy.updateMatrix();
        fenceRailRef.current!.setMatrixAt(i, dummy.matrix);
      });
      fenceRailRef.current.instanceMatrix.needsUpdate = true;
      fenceRailRef.current.computeBoundingSphere();
    }
  }, [streetProps]);

  const halfRoad = roadLength / 2;
  const dashCount = Math.floor(roadLength / 9);

  return (
    <group name="street_environment">
      {/* Expansive Suburban Ground Plane extending cleanly to horizon fog */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]} receiveShadow>
        <planeGeometry args={[540, 540]} />
        <meshStandardMaterial
          color="#ffffff"
          map={textures.grass.map}
          normalMap={textures.grass.normalMap}
          roughnessMap={textures.grass.roughnessMap}
          roughness={0.95}
        />
      </mesh>

      {/* Asphalt Street (offset +0.02m Y to prevent Z-fighting) */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.02, 0]} receiveShadow>
        <planeGeometry args={[roadLength + 60, STREET_CONFIG.roadWidth]} />
        <meshStandardMaterial
          color="#ffffff"
          map={textures.asphalt.map}
          normalMap={textures.asphalt.normalMap}
          roughnessMap={textures.asphalt.roughnessMap}
          roughness={0.86}
        />
      </mesh>

      {/* Dashed muted yellow center road lines */}
      {Array.from({ length: dashCount }).map((_, i) => {
        const x = -halfRoad + 4 + i * 9;
        return (
          <mesh key={`dash_${i}`} rotation={[-Math.PI / 2, 0, 0]} position={[x, 0.032, 0]}>
            <planeGeometry args={[4.2, 0.16]} />
            <meshStandardMaterial color="#b99c4e" roughness={0.85} />
          </mesh>
        );
      })}

      {/* Crosswalk zebra stripes */}
      {[-16, 16].map((cx) =>
        Array.from({ length: 6 }).map((_, si) => (
          <mesh
            key={`cw_${cx}_${si}`}
            rotation={[-Math.PI / 2, 0, 0]}
            position={[cx, 0.032, -3.6 + si * 1.44]}
          >
            <planeGeometry args={[2.2, 0.62]} />
            <meshStandardMaterial color="#c9c6be" roughness={0.85} />
          </mesh>
        )),
      )}

      {/* Iron Street Manholes */}
      {[-32, 6, 44].map((mx) => (
        <mesh key={`mh_${mx}`} position={[mx, 0.035, 1.4]} rotation={[-Math.PI / 2, 0, 0]}>
          <circleGeometry args={[0.42, 16]} />
          <meshStandardMaterial color="#3c3f43" metalness={0.7} roughness={0.55} />
        </mesh>
      ))}

      {/* Raised Concrete Sidewalks & Curbs (North & South) */}
      {[-1, 1].map((sign) => (
        <mesh
          key={`sw_${sign}`}
          position={[0, STREET_CONFIG.sidewalkHeight / 2, sign * (STREET_CONFIG.roadWidth / 2 + STREET_CONFIG.sidewalkWidth / 2)]}
          receiveShadow
          castShadow
        >
          <boxGeometry args={[roadLength + 60, STREET_CONFIG.sidewalkHeight, STREET_CONFIG.sidewalkWidth]} />
          <meshStandardMaterial
            color="#c2beb6"
            map={textures.concrete.map}
            normalMap={textures.concrete.normalMap}
            roughness={0.88}
          />
        </mesh>
      ))}

      {/* Per-house concrete driveways, front walkways, mailboxes, and trash bins (exact collider coords) */}
      {streetProps.lotProps.map((lp) => (
        <group key={`lot_props_${lp.houseId}`}>
          <mesh
            position={[lp.driveCenter.x, lp.driveCenter.y, lp.driveCenter.z]}
            rotation={[-Math.PI / 2, 0, 0]}
            receiveShadow
          >
            <planeGeometry args={[lp.driveWidth, lp.driveLength]} />
            <meshStandardMaterial color="#b3afa6" roughness={0.89} />
          </mesh>
          {[-6, -2, 2, 6].map((offset) => (
            <mesh
              key={offset}
              position={[lp.driveCenter.x, lp.driveCenter.y + 0.004, lp.driveCenter.z + offset]}
              rotation={[-Math.PI / 2, 0, 0]}
            >
              <planeGeometry args={[lp.driveWidth - 0.06, 0.05]} />
              <meshBasicMaterial color="#73706a" />
            </mesh>
          ))}
          <mesh
            position={[lp.walkCenter.x, lp.walkCenter.y, lp.walkCenter.z]}
            rotation={[-Math.PI / 2, 0, 0]}
            receiveShadow
          >
            <planeGeometry args={[1.8, lp.walkLength]} />
            <meshStandardMaterial color="#bfb9af" roughness={0.86} />
          </mesh>

          {/* Mailbox */}
          <group position={[lp.mailboxPos.x, 0, lp.mailboxPos.z]} rotation={[0, lp.rotationY, 0]}>
            <mesh position={[0, 0.56, 0]} castShadow>
              <boxGeometry args={[0.1, 1.12, 0.1]} />
              <meshStandardMaterial color="#594738" roughness={0.85} />
            </mesh>
            <mesh position={[0, 1.16, 0.05]} castShadow>
              <boxGeometry args={[0.24, 0.22, 0.46]} />
              <meshStandardMaterial color="#383d42" metalness={0.55} roughness={0.45} />
            </mesh>
            <mesh position={[0.135, 1.22, 0.12]}>
              <boxGeometry args={[0.02, 0.16, 0.06]} />
              <meshStandardMaterial color="#a63c2e" roughness={0.55} />
            </mesh>
          </group>

          {/* Wheeled Suburban Trash Bin */}
          <group position={[lp.binPos.x, 0, lp.binPos.z]} rotation={[0, lp.rotationY, 0]}>
            <mesh position={[0, 0.48, 0]} castShadow receiveShadow>
              <boxGeometry args={[0.56, 0.94, 0.54]} />
              <meshStandardMaterial color="#3d4940" roughness={0.65} />
            </mesh>
            <mesh position={[0, 0.98, 0]} castShadow>
              <boxGeometry args={[0.6, 0.08, 0.58]} />
              <meshStandardMaterial color="#303832" roughness={0.6} />
            </mesh>
          </group>
        </group>
      ))}

      {/* Distant Rolling Suburban Horizon Hills */}
      {[
        { pos: [-85, -2.5, -124] as [number, number, number], s: [76, 12, 44] as [number, number, number] },
        { pos: [15, -3.0, -132] as [number, number, number], s: [88, 14, 48] as [number, number, number] },
        { pos: [108, -2.5, -120] as [number, number, number], s: [74, 11, 42] as [number, number, number] },
        { pos: [-75, -2.8, 126] as [number, number, number], s: [82, 12, 46] as [number, number, number] },
        { pos: [55, -2.8, 128] as [number, number, number], s: [90, 13, 48] as [number, number, number] },
      ].map((hill, idx) => (
        <mesh key={`hill_${idx}`} position={hill.pos} scale={hill.s}>
          <sphereGeometry args={[1, 14, 10]} />
          <meshStandardMaterial color="#58694a" roughness={0.96} />
        </mesh>
      ))}

      {/* Fire Hydrants */}
      {streetProps.hydrants.map((hx) => (
        <group key={`hyd_${hx}`} position={[hx, 0.14, 5.55]}>
          <mesh position={[0, 0.34, 0]} castShadow>
            <cylinderGeometry args={[0.14, 0.17, 0.68, 10]} />
            <meshStandardMaterial color="#9e3529" roughness={0.45} metalness={0.35} />
          </mesh>
          <mesh position={[0, 0.72, 0]} castShadow>
            <sphereGeometry args={[0.15, 10, 8]} />
            <meshStandardMaterial color="#9e3529" roughness={0.45} metalness={0.35} />
          </mesh>
          <mesh position={[0, 0.48, 0]} rotation={[0, 0, Math.PI / 2]}>
            <cylinderGeometry args={[0.065, 0.065, 0.42, 8]} />
            <meshStandardMaterial color="#878b90" metalness={0.7} roughness={0.35} />
          </mesh>
        </group>
      ))}

      {/* Street Park Benches */}
      {streetProps.benches.map((b, i) => (
        <group key={`bench_${i}`} position={[b.x, 0.14, b.z]} rotation={[0, b.rotY, 0]}>
          <mesh position={[0, 0.46, 0]} castShadow receiveShadow>
            <boxGeometry args={[1.8, 0.08, 0.52]} />
            <meshStandardMaterial color="#6e543d" roughness={0.82} />
          </mesh>
          <mesh position={[0, 0.78, -0.22]} rotation={[0.15, 0, 0]} castShadow>
            <boxGeometry args={[1.8, 0.34, 0.07]} />
            <meshStandardMaterial color="#6e543d" roughness={0.82} />
          </mesh>
          {[-0.75, 0.75].map((lx) => (
            <mesh key={lx} position={[lx, 0.24, 0]} castShadow>
              <boxGeometry args={[0.1, 0.48, 0.48]} />
              <meshStandardMaterial color="#2f3337" metalness={0.65} roughness={0.45} />
            </mesh>
          ))}
        </group>
      ))}

      {/* Wooden Power Poles + Crossarms */}
      {streetProps.poles.map((px) => (
        <group key={`pole_${px}`} position={[px, 0, -8.3]}>
          <mesh position={[0, 4.4, 0]} castShadow>
            <cylinderGeometry args={[0.11, 0.16, 8.8, 10]} />
            <meshStandardMaterial color="#59493b" roughness={0.92} />
          </mesh>
          <mesh position={[0, 8.2, 0]} castShadow>
            <boxGeometry args={[2.1, 0.12, 0.14]} />
            <meshStandardMaterial color="#524336" roughness={0.9} />
          </mesh>
        </group>
      ))}
      <mesh position={[0, 8.22, -8.3]}>
        <boxGeometry args={[172, 0.035, 0.035]} />
        <meshBasicMaterial color="#1f2124" />
      </mesh>
      <mesh position={[0, 8.14, -8.0]}>
        <boxGeometry args={[172, 0.03, 0.03]} />
        <meshBasicMaterial color="#1f2124" />
      </mesh>

      {/* Street Lamps */}
      {streetProps.lamps.map((l, i) => (
        <StreetLamp key={`lamp_${i}`} position={l.pos} rotationY={l.rotY} isNight={isNight} />
      ))}

      {/* Composite Parked Cars */}
      {streetProps.cars.map((c) => (
        <ParkedCar
          key={c.id}
          position={c.pos}
          rotationY={c.rotY}
          color={c.color}
          isNight={isNight}
          shadowTex={shadowTex}
        />
      ))}

      {/* Instanced Deciduous Trees */}
      <instancedMesh
        ref={trunkRef}
        args={[undefined, undefined, streetProps.trees.length]}
        castShadow
        receiveShadow
      >
        <cylinderGeometry args={[0.18, 0.34, 3.3, 7]} />
        <meshStandardMaterial color="#574637" roughness={0.94} />
      </instancedMesh>
      <instancedMesh
        ref={crownARef}
        args={[undefined, undefined, streetProps.trees.length]}
        castShadow
        receiveShadow
      >
        <icosahedronGeometry args={[2.0, 0]} />
        <meshStandardMaterial color="#ffffff" roughness={0.92} flatShading />
      </instancedMesh>
      <instancedMesh
        ref={crownBRef}
        args={[undefined, undefined, streetProps.trees.length]}
        castShadow
      >
        <icosahedronGeometry args={[1.55, 0]} />
        <meshStandardMaterial color="#ffffff" roughness={0.92} flatShading />
      </instancedMesh>

      {/* Instanced Bushes */}
      <instancedMesh
        ref={bushRef}
        args={[undefined, undefined, streetProps.bushes.length]}
        castShadow
        receiveShadow
      >
        <icosahedronGeometry args={[0.64, 0]} />
        <meshStandardMaterial color="#ffffff" roughness={0.94} flatShading />
      </instancedMesh>

      {/* Instanced Wooden Perimeter Fence Posts & Rails */}
      <instancedMesh
        ref={fencePostRef}
        args={[undefined, undefined, streetProps.fencePosts.length]}
        castShadow
        receiveShadow
      >
        <boxGeometry args={[0.12, 1.56, 0.12]} />
        <meshStandardMaterial color="#685644" roughness={0.9} />
      </instancedMesh>
      <instancedMesh
        ref={fenceRailRef}
        args={[undefined, undefined, streetProps.fenceRails.length]}
        castShadow
        receiveShadow
      >
        <boxGeometry args={[1.0, 1.38, 0.05]} />
        <meshStandardMaterial color="#73604c" roughness={0.9} />
      </instancedMesh>
    </group>
  );
}
